{
  "name": "crypto-dashboard-frontend",
  "version": "1.0.0",
  "private": true,
  "dependencies": {
    "react": "^18.2.0",
    "react-dom": "^18.2.0",
    "react-scripts": "5.0.1",
    "axios": "^1.6.0",
    "recharts": "^2.10.3"
  },
  "scripts": {
    "start": "react-scripts start",
    "build": "react-scripts build",
    "test": "react-scripts test",
    "eject": "react-scripts eject"
  },
  "eslintConfig": {
    "extends": [
      "react-app"
    ]
  },
  "browserslist": {
    "production": [
      ">0.2%",
      "not dead",
      "not op_mini all"
    ],
    "development": [
      "last 1 chrome version",
      "last 1 firefox version",
      "last 1 safari version"
    ]
  },
  "proxy": "http://localhost:5001"
}

import React, { useState, useEffect } from 'react';
import './styles/App.css';
import Header from './components/Header';
import WatchlistSection from './components/WatchlistSection';
import MainContent from './components/MainContent';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorMessage from './components/ErrorMessage';
import { watchlistAPI } from './services/api';

function App() {
  // Watchlist state
  const [watchlist, setWatchlist] = useState([]);
  const [watchlistLoading, setWatchlistLoading] = useState(true);
  const [watchlistError, setWatchlistError] = useState(null);

  // Selected asset state
  const [selectedAsset, setSelectedAsset] = useState(null);

  // Active tab state
  const [activeTab, setActiveTab] = useState('news');

  // Load watchlist on mount
  useEffect(() => {
    loadWatchlist();
  }, []);

  // Auto-select first asset when watchlist loads
  useEffect(() => {
    if (watchlist.length > 0 && !selectedAsset) {
      setSelectedAsset(watchlist[0]);
    }
  }, [watchlist, selectedAsset]);

  const loadWatchlist = async () => {
    setWatchlistLoading(true);
    setWatchlistError(null);

    try {
      const response = await watchlistAPI.getAll();
      setWatchlist(response.data.assets || []);
    } catch (error) {
      console.error('Error loading watchlist:', error);
      setWatchlistError(error.error?.message || 'Failed to load watchlist');
    } finally {
      setWatchlistLoading(false);
    }
  };

  const handleAddAsset = async (asset) => {
    try {
      const response = await watchlistAPI.add(asset);
      setWatchlist(response.data.assets);
      return { success: true };
    } catch (error) {
      console.error('Error adding asset:', error);
      return {
        success: false,
        error: error.error?.message || 'Failed to add asset'
      };
    }
  };

  const handleRemoveAsset = async (asset) => {
    try {
      const response = await watchlistAPI.remove(asset);
      setWatchlist(response.data.assets);

      // If removed asset was selected, select first remaining asset
      if (selectedAsset === asset) {
        const newWatchlist = response.data.assets;
        setSelectedAsset(newWatchlist.length > 0 ? newWatchlist[0] : null);
      }

      return { success: true };
    } catch (error) {
      console.error('Error removing asset:', error);
      return {
        success: false,
        error: error.error?.message || 'Failed to remove asset'
      };
    }
  };

  return (
    <div className="app">
      {/* Skip to main content for keyboard users */}
      <a href="#main-content" className="skip-link">
        Skip to main content
      </a>

      <Header />

      <main className="app-main" id="main-content">
        <div className="app-container">
          {/* Watchlist Section - Left sidebar on desktop */}
          <aside 
            className="app-sidebar"
            role="complementary"
            aria-label="Watchlist"
          >
            {watchlistLoading ? (
              <div className="section-loading">
                <LoadingSpinner size="small" />
                <p className="sr-only">Loading watchlist...</p>
              </div>
            ) : watchlistError ? (
              <ErrorMessage 
                message={watchlistError}
                onRetry={loadWatchlist}
              />
            ) : (
              <WatchlistSection
                watchlist={watchlist}
                selectedAsset={selectedAsset}
                onSelectAsset={setSelectedAsset}
                onAddAsset={handleAddAsset}
                onRemoveAsset={handleRemoveAsset}
              />
            )}
          </aside>

          {/* Main Content - Right section on desktop */}
          <section 
            className="app-content"
            role="main"
            aria-label="Asset details"
          >
            {!selectedAsset ? (
              <div className="empty-state fade-in">
                <h2>Welcome to Crypto Trading Dashboard</h2>
                <p>
                  {watchlist.length === 0 
                    ? 'Add your first asset to get started' 
                    : 'Select an asset from your watchlist to view market data and news'}
                </p>
              </div>
            ) : (
              <MainContent
                selectedAsset={selectedAsset}
                activeTab={activeTab}
                onTabChange={setActiveTab}
              />
            )}
          </section>
        </div>
      </main>

      <footer className="app-footer" role="contentinfo">
        <p>
          Data provided by{' '}
          <a 
            href="https://www.coingecko.com/" 
            target="_blank" 
            rel="noopener noreferrer"
            aria-label="CoinGecko (opens in new tab)"
          >
            CoinGecko
          </a>
          {' '}and{' '}
          <a 
            href="https://newsapi.org/" 
            target="_blank" 
            rel="noopener noreferrer"
            aria-label="NewsAPI (opens in new tab)"
          >
            NewsAPI
          </a>
        </p>
      </footer>
    </div>
  );
}

export default App;

import axios from 'axios';

// Create axios instance with default config
export const apiClient = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:5000/api',
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Response interceptor to handle standard error format
apiClient.interceptors.response.use(
  response => response.data,
  error => {
    if (error.response) {
      // API returned error response
      return Promise.reject(error.response.data);
    }
    if (error.code === 'ECONNABORTED') {
      return Promise.reject({
        success: false,
        error: {
          code: 'timeout_error',
          message: 'Request timed out. Please try again.'
        }
      });
    }
    // Network error
    return Promise.reject({
      success: false,
      error: {
        code: 'network_error',
        message: 'Network error. Check your connection and ensure the backend server is running.'
      }
    });
  }
);

// API functions
export const watchlistAPI = {
  getAll: () => apiClient.get('/watchlist'),
  add: (asset) => apiClient.post('/watchlist', { asset }),
  remove: (asset) => apiClient.delete(`/watchlist/${asset}`)
};

export const marketAPI = {
  getOHLCV: (asset) => apiClient.get(`/market/${asset}`)
};

export const newsAPI = {
  getArticles: (asset) => apiClient.get(`/news/${asset}`)
};

import React from 'react';
import './MainContent.css';
import NewsTab from './NewsTab';
import MarketDataTab from './MarketDataTab';

function MainContent({ selectedAsset, activeTab, onTabChange }) {
  const handleTabKeyDown = (e, tab) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onTabChange(tab);
    }

    // Arrow key navigation between tabs
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
      e.preventDefault();
      const newTab = activeTab === 'news' ? 'market' : 'news';
      onTabChange(newTab);
      // Focus the new tab
      setTimeout(() => {
        const newTabButton = document.querySelector(`[data-tab="${newTab}"]`);
        if (newTabButton) newTabButton.focus();
      }, 0);
    }
  };

  return (
    <div className="main-content">
      <div className="asset-header">
        <h2 className="asset-title">{selectedAsset}</h2>
      </div>

      {/* Tab Navigation */}
      <div 
        className="tabs" 
        role="tablist" 
        aria-label="Asset data views"
      >
        <button
          className={`tab ${activeTab === 'news' ? 'tab--active' : ''}`}
          role="tab"
          aria-selected={activeTab === 'news'}
          aria-controls="news-panel"
          id="news-tab"
          data-tab="news"
          onClick={() => onTabChange('news')}
          onKeyDown={(e) => handleTabKeyDown(e, 'news')}
          tabIndex={activeTab === 'news' ? 0 : -1}
        >
          <span className="tab-icon" aria-hidden="true">📰</span>
          News
        </button>

        <button
          className={`tab ${activeTab === 'market' ? 'tab--active' : ''}`}
          role="tab"
          aria-selected={activeTab === 'market'}
          aria-controls="market-panel"
          id="market-tab"
          data-tab="market"
          onClick={() => onTabChange('market')}
          onKeyDown={(e) => handleTabKeyDown(e, 'market')}
          tabIndex={activeTab === 'market' ? 0 : -1}
        >
          <span className="tab-icon" aria-hidden="true">📊</span>
          Market Data
        </button>
      </div>

      {/* Tab Panels */}
      <div className="tab-panels">
        {activeTab === 'news' && (
          <div
            role="tabpanel"
            id="news-panel"
            aria-labelledby="news-tab"
            className="tab-panel fade-in"
          >
            <NewsTab asset={selectedAsset} />
          </div>
        )}

        {activeTab === 'market' && (
          <div
            role="tabpanel"
            id="market-panel"
            aria-labelledby="market-tab"
            className="tab-panel fade-in"
          >
            <MarketDataTab asset={selectedAsset} />
          </div>
        )}
      </div>
    </div>
  );
}

export default MainContent;

import React, { useState, useEffect } from 'react';
import './MarketDataTab.css';
import LoadingSpinner from './LoadingSpinner';
import ErrorMessage from './ErrorMessage';
import { marketAPI } from '../services/api';
import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend
} from 'recharts';

function MarketDataTab({ asset }) {
  const [ohlcvData, setOhlcvData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastFetched, setLastFetched] = useState(null);

  useEffect(() => {
    fetchMarketData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [asset]);

  const fetchMarketData = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await marketAPI.getOHLCV(asset);
      setOhlcvData(response.data.ohlcv || []);
      setLastFetched(response.data.fetchedAt);
    } catch (err) {
      console.error('Error fetching market data:', err);
      setError(err.error || { message: 'Failed to fetch market data' });
    } finally {
      setLoading(false);
    }
  };

  // Transform OHLCV data for candlestick rendering
  const chartData = ohlcvData.map((candle) => {
    const isGreen = candle.close >= candle.open;
    return {
      timestamp: new Date(candle.timestamp).toLocaleTimeString('en-US', {
        hour: 'numeric',
        hour12: false
      }),
      open: candle.open,
      high: candle.high,
      low: candle.low,
      close: candle.close,
      // For candlestick body
      bodyBottom: Math.min(candle.open, candle.close),
      bodyTop: Math.max(candle.open, candle.close),
      bodyHeight: Math.abs(candle.close - candle.open),
      // For wicks
      upperWick: candle.high - Math.max(candle.open, candle.close),
      lowerWick: Math.min(candle.open, candle.close) - candle.low,
      // Color
      isGreen: isGreen,
      fill: isGreen ? '#4caf50' : '#f44336'
    };
  });

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      return (
        <div className="chart-tooltip" role="tooltip">
          <p className="tooltip-time">{data.timestamp}:00</p>
          <p className="tooltip-item">
            <strong>Open:</strong> ${data.open.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
          <p className="tooltip-item">
            <strong>High:</strong> ${data.high.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
          <p className="tooltip-item">
            <strong>Low:</strong> ${data.low.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
          <p className="tooltip-item">
            <strong>Close:</strong> ${data.close.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
        </div>
      );
    }
    return null;
  };

  // Render candlestick shape
  const renderCandlestick = (props) => {
    const { x, y, width, height, payload } = props;
    if (!payload) return null;

    const candleWidth = Math.min(width * 0.6, 20);
    const wickWidth = 2;
    const candleX = x + width / 2 - candleWidth / 2;
    const wickX = x + width / 2 - wickWidth / 2;

    return (
      <g>
        {/* Upper wick */}
        <rect
          x={wickX}
          y={y}
          width={wickWidth}
          height={height}
          fill={payload.fill}
        />
        {/* Candle body - drawn separately to ensure visibility */}
        <rect
          x={candleX}
          y={y + (height - payload.bodyHeight * height / (payload.high - payload.low))}
          width={candleWidth}
          height={Math.max(payload.bodyHeight * height / (payload.high - payload.low), 1)}
          fill={payload.fill}
          stroke={payload.fill}
          strokeWidth={1}
        />
      </g>
    );
  };

  return (
    <div className="market-data-tab">
      <div className="market-header">
        <h3 className="market-title">24-Hour Price Chart (1h candles)</h3>
        <button
          className="refresh-button"
          onClick={fetchMarketData}
          disabled={loading}
          aria-label={`Refresh market data for ${asset}`}
        >
          <span className={`refresh-icon ${loading ? 'refresh-icon--spinning' : ''}`} aria-hidden="true">
            ↻
          </span>
          Refresh
        </button>
      </div>

      {loading ? (
        <LoadingSpinner message={`Loading market data for ${asset}...`} />
      ) : error ? (
        <ErrorMessage
          message={error.message}
          onRetry={fetchMarketData}
        />
      ) : ohlcvData.length === 0 ? (
        <div className="empty-state" role="status">
          <p>No market data available for {asset}</p>
        </div>
      ) : (
        <>
          <div 
            className="chart-container" 
            role="img" 
            aria-label={`Candlestick chart showing ${asset} price over 24 hours`}
          >
            <ResponsiveContainer width="100%" height={400}>
              <ComposedChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 20 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
                <XAxis
                  dataKey="timestamp"
                  tick={{ fill: '#666' }}
                  style={{ fontSize: '12px' }}
                  aria-label="Time"
                />
                <YAxis
                  domain={['dataMin - 100', 'dataMax + 100']}
                  tick={{ fill: '#666' }}
                  style={{ fontSize: '12px' }}
                  tickFormatter={(value) => `$${value.toLocaleString()}`}
                  aria-label="Price in USD"
                />
                <Tooltip content={<CustomTooltip />} />

                {/* Render as bars to simulate candlesticks */}
                <Bar
                  dataKey="high"
                  fill="transparent"
                  shape={renderCandlestick}
                  isAnimationActive={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>

          {/* Price summary */}
          {ohlcvData.length > 0 && (
            <div className="price-summary" role="region" aria-label="Price summary">
              <div className="price-stat">
                <span className="price-label">Current:</span>
                <span className="price-value">
                  ${ohlcvData[ohlcvData.length - 1].close.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>
              <div className="price-stat">
                <span className="price-label">24h High:</span>
                <span className="price-value">
                  ${Math.max(...ohlcvData.map(d => d.high)).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>
              <div className="price-stat">
                <span className="price-label">24h Low:</span>
                <span className="price-value">
                  ${Math.min(...ohlcvData.map(d => d.low)).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>
            </div>
          )}

          {lastFetched && (
            <p className="last-fetched" role="status" aria-live="polite">
              Last updated: {new Date(lastFetched).toLocaleString()}
            </p>
          )}
        </>
      )}
    </div>
  );
}

export default MarketDataTab;

import React, { useState, useEffect } from 'react';
import './NewsTab.css';
import LoadingSpinner from './LoadingSpinner';
import ErrorMessage from './ErrorMessage';
import { newsAPI } from '../services/api';

function NewsTab({ asset }) {
  const [articles, setArticles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastFetched, setLastFetched] = useState(null);
  const [rateLimitInfo, setRateLimitInfo] = useState(null);

  useEffect(() => {
    fetchNews();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [asset]);

  const fetchNews = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await newsAPI.getArticles(asset);
      setArticles(response.data.articles || []);
      setLastFetched(response.data.fetchedAt);
      setRateLimitInfo(response.data.rateLimitInfo);
    } catch (err) {
      console.error('Error fetching news:', err);
      setError(err.error || { message: 'Failed to fetch news' });
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffHours / 24);

    if (diffHours < 1) {
      return 'Just now';
    } else if (diffHours < 24) {
      return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    } else if (diffDays < 7) {
      return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
    } else {
      return date.toLocaleDateString('en-US', { 
        month: 'short', 
        day: 'numeric', 
        year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined 
      });
    }
  };

  const isRateLimited = error && error.code === 'newsapi_rate_limit_exceeded';

  return (
    <div className="news-tab">
      <div className="news-header">
        <h3 className="news-title">Latest News for {asset}</h3>
        <button
          className="refresh-button"
          onClick={fetchNews}
          disabled={loading || isRateLimited}
          aria-label={`Refresh news for ${asset}`}
        >
          <span className={`refresh-icon ${loading ? 'refresh-icon--spinning' : ''}`} aria-hidden="true">
            ↻
          </span>
          Refresh
        </button>
      </div>

      {rateLimitInfo && (
        <div className="rate-limit-info" role="status" aria-live="polite">
          <p>
            News requests today: {rateLimitInfo.requestsUsedToday} / 100
            {rateLimitInfo.requestsRemaining === 0 && (
              <span className="rate-limit-warning"> (Limit reached)</span>
            )}
          </p>
        </div>
      )}

      {loading ? (
        <LoadingSpinner message={`Loading news for ${asset}...`} />
      ) : error ? (
        <ErrorMessage
          message={error.message}
          details={error.code === 'newsapi_rate_limit_exceeded' 
            ? `Come back at ${new Date(error.details?.resetTime).toLocaleString('en-US', { timeZone: 'UTC' })} UTC to refresh news.`
            : null
          }
          onRetry={!isRateLimited ? fetchNews : null}
        />
      ) : articles.length === 0 ? (
        <div className="empty-state" role="status">
          <p>No news articles found for {asset}</p>
        </div>
      ) : (
        <>
          <div 
            className="articles-list" 
            role="feed" 
            aria-label={`News articles for ${asset}`}
          >
            {articles.map((article, index) => (
              <article key={article.id} className="article-card fade-in">
                {article.imageUrl && (
                  <div className="article-image-container">
                    <img
                      src={article.imageUrl}
                      alt={`Thumbnail for ${article.title}`}
                      className="article-image"
                      loading="lazy"
                      onError={(e) => {
                        e.target.style.display = 'none';
                      }}
                    />
                  </div>
                )}
                <div className="article-content">
                  <h4 className="article-title">
                    <a
                      href={article.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      aria-label={`Read: ${article.title} (opens in new tab)`}
                    >
                      {article.title}
                    </a>
                  </h4>
                  <div className="article-meta">
                    <span className="article-source">{article.source}</span>
                    <span className="article-separator" aria-hidden="true">•</span>
                    <time 
                      className="article-date"
                      dateTime={article.publishedAt}
                    >
                      {formatDate(article.publishedAt)}
                    </time>
                  </div>
                  {article.description && (
                    <p className="article-description">
                      {article.description.length > 150
                        ? `${article.description.substring(0, 150)}...`
                        : article.description}
                    </p>
                  )}
                </div>
              </article>
            ))}
          </div>

          {lastFetched && (
            <p className="last-fetched" role="status" aria-live="polite">
              Last updated: {new Date(lastFetched).toLocaleString()}
            </p>
          )}
        </>
      )}
    </div>
  );
}

export default NewsTab;

import React, { useState } from 'react';
import './WatchlistSection.css';

function WatchlistSection({ 
  watchlist, 
  selectedAsset, 
  onSelectAsset, 
  onAddAsset, 
  onRemoveAsset 
}) {
  const [newAsset, setNewAsset] = useState('');
  const [addError, setAddError] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [removingAsset, setRemovingAsset] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setAddError('');

    const symbol = newAsset.trim().toUpperCase();

    // Client-side validation
    if (!symbol) {
      setAddError('Please enter an asset symbol');
      return;
    }

    if (!/^[A-Z]{2,10}$/.test(symbol)) {
      setAddError('Asset symbol must be 2-10 uppercase letters');
      return;
    }

    setIsAdding(true);

    const result = await onAddAsset(symbol);

    if (result.success) {
      setNewAsset('');
      setAddError('');
      // Announce success to screen readers
      const announcement = document.createElement('div');
      announcement.setAttribute('role', 'status');
      announcement.setAttribute('aria-live', 'polite');
      announcement.className = 'sr-only';
      announcement.textContent = `${symbol} added to watchlist`;
      document.body.appendChild(announcement);
      setTimeout(() => document.body.removeChild(announcement), 1000);
    } else {
      setAddError(result.error);
    }

    setIsAdding(false);
  };

  const handleRemove = async (asset) => {
    setRemovingAsset(asset);
    const result = await onRemoveAsset(asset);

    if (result.success) {
      // Announce success to screen readers
      const announcement = document.createElement('div');
      announcement.setAttribute('role', 'status');
      announcement.setAttribute('aria-live', 'polite');
      announcement.className = 'sr-only';
      announcement.textContent = `${asset} removed from watchlist`;
      document.body.appendChild(announcement);
      setTimeout(() => document.body.removeChild(announcement), 1000);
    }

    setRemovingAsset(null);
  };

  const handleKeyDown = (e, asset) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSelectAsset(asset);
    }
  };

  return (
    <div className="watchlist-section">
      <h2 className="watchlist-title">Your Watchlist</h2>

      {/* Add Asset Form */}
      <form 
        className="add-asset-form" 
        onSubmit={handleSubmit}
        aria-label="Add asset to watchlist"
      >
        <label htmlFor="new-asset-input" className="sr-only">
          New asset symbol
        </label>
        <input
          id="new-asset-input"
          type="text"
          className="add-asset-input"
          placeholder="Enter symbol (e.g., BTC)"
          value={newAsset}
          onChange={(e) => setNewAsset(e.target.value.toUpperCase())}
          disabled={isAdding}
          aria-invalid={addError ? 'true' : 'false'}
          aria-describedby={addError ? 'add-asset-error' : undefined}
        />
        <button
          type="submit"
          className="add-asset-button"
          disabled={isAdding}
          aria-label="Add asset to watchlist"
        >
          {isAdding ? 'Adding...' : 'Add'}
        </button>
      </form>

      {addError && (
        <p 
          id="add-asset-error" 
          className="add-asset-error" 
          role="alert"
          aria-live="assertive"
        >
          {addError}
        </p>
      )}

      {/* Watchlist */}
      {watchlist.length === 0 ? (
        <div className="empty-watchlist" role="status">
          <p>No assets in your watchlist</p>
          <p className="empty-watchlist-hint">Add your first asset above to get started</p>
        </div>
      ) : (
        <ul 
          className="watchlist"
          aria-label="Crypto assets"
        >
          {watchlist.map((asset) => (
            <li
              key={asset}
              className={`watchlist-item ${selectedAsset === asset ? 'watchlist-item--selected' : ''}`}
            >
              <button
                className="watchlist-item-button"
                onClick={() => onSelectAsset(asset)}
                onKeyDown={(e) => handleKeyDown(e, asset)}
                aria-label={`Select ${asset}`}
                aria-current={selectedAsset === asset ? 'true' : 'false'}
              >
                <span className="watchlist-item-symbol">{asset}</span>
              </button>
              <button
                className="watchlist-item-remove"
                onClick={() => handleRemove(asset)}
                disabled={removingAsset === asset}
                aria-label={`Remove ${asset} from watchlist`}
                title={`Remove ${asset}`}
              >
                {removingAsset === asset ? '...' : '×'}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

